{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 내용을 확인하고, 의심스러운 용량을 발견했을 때 투약을 멈춘 뒤 담당자에게 확인하는 판단과 행동을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력되어 투약 전 확인이 필요했던 상황을 설명한다.",
          "task": "환자와 처방 내용을 확인하고, 용량의 적절성이 확인되기 전에는 투약하지 않아야 했던 책임을 설명한다.",
          "action": "환자 및 약물·용량·경로·시간을 확인한 절차와 용량을 의심한 근거를 제시하고, 투약을 중단한 상태에서 담당의에게 확인한 행동을 설명한다.",
          "result": "담당의 확인으로 처방 입력 오류가 확인되었으며, 확인되지 않은 처방이 그대로 투약되지 않았음을 설명한다."
        },
        "expectedEvidence": [
          "투약 전 환자 및 약물·용량·경로·시간을 확인한 구체적인 절차",
          "처방 용량을 의심하게 된 비교 정보와 확인이 필요하다고 판단한 근거",
          "의심이 해소되기 전 투약을 멈추고 담당의에게 확인한 행동",
          "담당의의 확인 내용과 그에 따른 처방 수행 여부"
        ]
      },
      "question": "진통제 용량이 평소의 두 배로 처방됐던 사례에서, 투약 전 담당의에게 확인해야 한다고 판단했던 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 소개하고 본인이 했던 일을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "환자 및 약물·용량·경로·시간의 확인 절차를 실제 행동으로 구체적으로 설명한다.",
            "처방 용량을 의심한 근거가 명확하며, 투약을 멈추고 담당의에게 확인한 행동이 연결된다.",
            "담당의가 확인한 내용과 확인되지 않은 처방의 투약을 방지한 결과를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량을 의심한 근거와 투약을 멈추고 담당의에게 확인한 행동은 드러난다.",
            "환자 및 처방 확인 절차의 일부가 생략되거나, 담당의 확인 이후의 결과가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "용량이 이상했다고만 답하며 확인이 필요했던 근거와 실제 확인 행동을 설명하지 못한다.",
            "의심스러운 처방을 확인 없이 수행하거나, 확인 전 투약을 멈추었다는 핵심 근거가 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태를 주기적으로 관찰하여 변화를 정확히 기록하고, 이상 징후 보고와 다음 근무자 인수인계로 연결해 정보 누락을 방지하는 행동을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 활력징후, 통증 또는 의식 수준을 관찰하며 상태 변화를 확인했던 병동 근무 사례를 설명한다.",
          "task": "정해진 주기에 따라 상태를 관찰하고, 변화 내용을 간호 기록과 담당 의사 보고 및 다음 근무자 인수인계에 반영해야 했던 역할을 설명한다.",
          "action": "관찰 시점과 상태 변화를 정확히 기록하고, 이상 징후를 담당 의사에게 보고했으며, 기록된 변화가 다음 근무자에게 빠짐없이 전달되었는지 확인한 방법을 설명한다.",
          "result": "관찰한 상태 변화와 보고 내용이 기록 및 인수인계에 반영되었음을 무엇으로 확인했는지 설명한다."
        },
        "expectedEvidence": [
          "정해진 관찰 주기와 이전 관찰 내용 대비 환자 상태 변화",
          "관찰 시점과 상태 변화를 정확히 남긴 간호 기록 내용",
          "이상 징후를 담당 의사에게 보고한 시점과 전달 내용",
          "간호 기록의 상태 변화가 다음 근무자 인수인계에 누락 없이 반영되었는지 확인한 방법"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자를 관찰하셨을 때, 환자 상태 변화가 간호 기록에서 다음 근무자 인수인계로 이어지도록 확인한 방법은 무엇이었나요?",
      "answerTip": "한 가지 사례를 골라 당시 본인이 했던 일을 차분히 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "정해진 주기에 따른 관찰과 이전 상태 대비 변화를 구체적으로 설명하고, 관찰 시점과 변화가 기록에 정확히 반영되었음을 보여 준다.",
            "이상 징후에 대한 담당 의사 보고 시점과 내용을 구체적으로 설명한다.",
            "기록된 상태 변화가 다음 근무자에게 누락 없이 전달되었는지 확인한 방법과 확인 결과가 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 변화를 기록하고 다음 근무자에게 전달한 행동은 확인되지만, 누락 여부를 확인한 방법이나 결과가 구체적이지 않다.",
            "관찰 주기, 기록 내용, 담당 의사 보고 중 일부 근거가 부족하나 상태 변화의 기록과 전달이라는 핵심 연결은 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "관찰하거나 기록했다는 일반적인 설명에 그쳐, 상태 변화가 인수인계로 연결되었다는 근거가 없다.",
            "이상 징후의 담당 의사 보고나 다음 근무자 전달이 빠져 있거나, 기록 및 전달 내용을 설명하지 못한다."
          ]
        }
      }
    }
  ]
}
